import { readFile, writeFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";
import { format } from "prettier";
const schema = new URL("../../control-plane/openapi.json", import.meta.url);
const output = new URL("../src/api/schema.d.ts", import.meta.url);
const source =
  "// Generated by npm run contract:types. Do not edit.\n" +
  astToString(await openapiTS(schema));
const formatted = await format(source, { parser: "typescript" });
if (process.argv.includes("--check")) {
  if ((await readFile(output, "utf8")) !== formatted)
    throw new Error("API types are stale. Run npm run contract:types.");
} else await writeFile(output, formatted);
